import React, { useState, useEffect } from 'react';
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
  useLocation,
  useNavigate
} from 'react-router-dom';

// AUTH
import Login from './components/Clients/Auth/Login';
import Register from './components/Clients/Auth/Register';
import ProtectedRoute from './components/Clients/Auth/ProtectedRoute';

// LAYOUTS
import Dashboard from './components/DashboardLayout';
import ClientLayout from './components/ClientLayout';

// CLIENT PAGES
import Home from './components/Clients/Home/Home';
import Services from './components/Clients/Services/Services';
import Portfolio from './components/Clients/Portfolio/Portfolio';
import Contact from './components/Clients/Contact/Contact';

// WIDGETS
import Header from './components/Clients/Widgets/Header/Header';
import Footer from './components/Clients/Widgets/Footer/Footer';

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState(null);
  const [userData, setUserData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  const location = useLocation();
  const navigate = useNavigate();

  // Vérifier session
  useEffect(() => {
    const storedUser = localStorage.getItem('userData');
    if (storedUser) {
      const user = JSON.parse(storedUser);
      setUserData(user);
      setUserRole(user.role);
      setIsAuthenticated(true);

      if (user.role === 'admin' && !location.pathname.startsWith('/admin')) {
        navigate('/admin', { replace: true });
      } else if (user.role === 'user' && location.pathname.startsWith('/admin')) {
        navigate('/', { replace: true });
      }
    }
    setIsLoading(false);
  }, []);

  const handleLogin = (data) => {
    localStorage.setItem('userData', JSON.stringify(data));
    setUserData(data);
    setUserRole(data.role);
    setIsAuthenticated(true);

    if (data.role === 'admin') navigate('/admin', { replace: true });
    else navigate('/', { replace: true });
  };

  const handleLogout = () => {
    localStorage.removeItem('userData');
    setUserData(null);
    setUserRole(null);
    setIsAuthenticated(false);
    navigate('/login', { replace: true });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white dark:bg-neutral-950">
        <div className="text-center">
          <div className="h-12 w-12 border-4 border-primary-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="mt-4 text-neutral-600 dark:text-neutral-400">Chargement...</p>
        </div>
      </div>
    );
  }

  return (
    <>
      {/* Header visible partout */}
      <Header isAuthenticated={isAuthenticated} onLogout={handleLogout} userData={userData} />

      <Routes>
        {/* LOGIN */}
        <Route
          path="/login"
          element={
            isAuthenticated ? (
              userRole === 'admin' ? <Navigate to="/admin" replace /> : <Navigate to="/" replace />
            ) : (
              <Login onLogin={handleLogin} />
            )
          }
        />

        {/* REGISTER */}
        <Route
          path="/register"
          element={
            isAuthenticated ? (
              userRole === 'admin' ? <Navigate to="/admin" replace /> : <Navigate to="/" replace />
            ) : (
              <Register />
            )
          }
        />

        {/* DASHBOARD ADMIN */}
        <Route
          path="/admin/*"
          element={
            <ProtectedRoute isAuthenticated={isAuthenticated} requiredRole="admin" userRole={userRole}>
              <Dashboard onLogout={handleLogout} />
            </ProtectedRoute>
          }
        />

        {/* CLIENT */}
        <Route path="/" element={<Home />} />
        <Route path="/services" element={<Services />} />
        <Route path="/portfolio" element={<Portfolio />} />
        <Route path="/contact" element={<Contact />} />

        {/* 404 */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>

      {/* Footer visible partout */}
      <Footer />
    </>
  );
}

export default function AppWrapper() {
  return (
    <Router>
      <App />
    </Router>
  );
}
